#!/usr/bin/env python3
"""Offline BGP relationship inference and route-leak scoring service."""

import sys
import json
import re
from fractions import Fraction
from itertools import product
from math import gcd


class Invalid(Exception):
    pass


def bad(*args, **kwargs):
    raise Invalid()


AS_RE = re.compile(r"[A-Za-z0-9_.-]{1,64}\Z")
TOP_KEYS = {"version", "ixps", "rib", "priors", "declared", "order", "queries"}
MAX_INPUT = 4194304

# c2p, p2p, p2c are represented by 0, 1, 2.
# g[L][R]
G = (
    (0, 0, 1),
    (1, 1, 2),
    (1, 1, 2),
)


def is_int(x):
    return type(x) is int


def asn_ok(x):
    return type(x) is int and 1 <= x <= 4294967295


def canonical(a, b):
    return (a, b) if a < b else (b, a)


def check_asn(x):
    if not asn_ok(x):
        raise Invalid()


def check_path(p):
    if type(p) is not list or len(p) > 64:
        raise Invalid()
    for x in p:
        check_asn(x)


def check_link(raw):
    if type(raw) is not list or len(raw) != 2:
        raise Invalid()
    u, v = raw
    check_asn(u)
    check_asn(v)
    if u == v:
        raise Invalid()
    return u, v


def check_threshold(raw):
    if type(raw) is not list or len(raw) != 2:
        raise Invalid()
    a, b = raw
    if not is_int(a) or not is_int(b):
        raise Invalid()
    if b < 1 or a < 0 or a > b or b > 1000000:
        raise Invalid()
    return a, b


def normalize_path(path, ixps):
    # Remove IXPs first, then collapse maximal adjacent duplicate runs in place.
    out = []
    for x in path:
        if x in ixps:
            continue
        if not out or out[-1] != x:
            out.append(x)
    return tuple(out)


def parse_request():
    raw = sys.stdin.buffer.read(MAX_INPUT + 1)
    if len(raw) > MAX_INPUT:
        raise Invalid()
    try:
        text = raw.decode("utf-8")
        obj = json.loads(
            text,
            object_pairs_hook=no_duplicate_object,
            parse_float=bad,
            parse_constant=bad,
        )
    except Invalid:
        raise
    except Exception:
        raise Invalid()
    return obj


def no_duplicate_object(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise Invalid()
        d[k] = v
    return d


def validate(data):
    if type(data) is not dict:
        raise Invalid()
    if set(data.keys()) != TOP_KEYS:
        raise Invalid()
    if not is_int(data["version"]) or data["version"] != 1:
        raise Invalid()

    ixps_raw = data["ixps"]
    if type(ixps_raw) is not list or len(ixps_raw) > 1024:
        raise Invalid()
    ixps = set()
    for x in ixps_raw:
        check_asn(x)
        if x in ixps:
            raise Invalid()
        ixps.add(x)

    rib_raw = data["rib"]
    if type(rib_raw) is not list or len(rib_raw) > 2000:
        raise Invalid()
    rib = []
    total_rib_path_len = 0
    for rec in rib_raw:
        if type(rec) is not dict or set(rec.keys()) != {"path", "count"}:
            raise Invalid()
        p = rec["path"]
        check_path(p)
        c = rec["count"]
        if not is_int(c) or c < 1 or c > 1000000:
            raise Invalid()
        total_rib_path_len += len(p)
        rib.append((p, c))
    if total_rib_path_len > 40000:
        raise Invalid()

    priors_raw = data["priors"]
    if type(priors_raw) is not list or len(priors_raw) > 2000:
        raise Invalid()
    priors = {}
    for rec in priors_raw:
        if type(rec) is not dict or set(rec.keys()) != {"link", "weights"}:
            raise Invalid()
        u, v = check_link(rec["link"])
        w = rec["weights"]
        if type(w) is not list or len(w) != 3:
            raise Invalid()
        for x in w:
            if not is_int(x) or x < 0 or x > 1000000:
                raise Invalid()
        s = w[0] + w[1] + w[2]
        if s <= 0:
            raise Invalid()
        e = canonical(u, v)
        if e in priors:
            raise Invalid()
        vec = (Fraction(w[0], s), Fraction(w[1], s), Fraction(w[2], s))
        if u > v:
            vec = (vec[2], vec[1], vec[0])
        priors[e] = vec

    declared_raw = data["declared"]
    if type(declared_raw) is not list or len(declared_raw) > 2000:
        raise Invalid()
    declared = {}
    rel_index = {"c2p": 0, "p2p": 1, "p2c": 2}
    for rec in declared_raw:
        if type(rec) is not dict or set(rec.keys()) != {"link", "rel"}:
            raise Invalid()
        u, v = check_link(rec["link"])
        rel = rec["rel"]
        if type(rel) is not str or rel not in rel_index:
            raise Invalid()
        e = canonical(u, v)
        if e in declared:
            raise Invalid()
        vec = [Fraction(0), Fraction(0), Fraction(0)]
        vec[rel_index[rel]] = Fraction(1)
        if u > v:
            vec.reverse()
        declared[e] = tuple(vec)

    order_raw = data["order"]
    if type(order_raw) is not list:
        raise Invalid()
    order = []
    order_seen = set()
    for rawlink in order_raw:
        if type(rawlink) is not list or len(rawlink) != 2:
            raise Invalid()
        u, v = rawlink
        check_asn(u)
        check_asn(v)
        if u >= v:
            raise Invalid()
        e = (u, v)
        if e in order_seen:
            raise Invalid()
        order_seen.add(e)
        order.append(e)

    queries_raw = data["queries"]
    if type(queries_raw) is not list or len(queries_raw) > 512:

    if type(queries_raw) is not list or len(queries_raw) > 512:
        raise Invalid()
    queries = []
    ids = set()
    for rec in queries_raw:
        if type(rec) is not dict or set(rec.keys()) != {"id", "path", "threshold"}:
            raise Invalid()
        qid = rec["id"]
        if type(qid) is not str or AS_RE.fullmatch(qid) is None:
            raise Invalid()
        if qid in ids:
            raise Invalid()
        ids.add(qid)
        p = rec["path"]
        check_path(p)
        th = check_threshold(rec["threshold"])
        queries.append((qid, p, th))

    return ixps, rib, priors, declared, order, queries


def peel(paths):
    """Return (rounds, core_paths). rounds maps removed canonical edge -> round."""
    current = dict(paths)
    rounds = {}
    rnd = 1
    while True:
        stats = {}
        for p in current:
            first = p[0]
            last = p[-1]
            prev = p[0]
            for cur in p[1:]:
                e = canonical(prev, cur)
                rec = stats.get(e)
                if rec is None:
                    rec = [True, True]
                    stats[e] = rec
                u, v = e
                if first != u and last != u:
                    rec[0] = False
                if first != v and last != v:
                    rec[1] = False
                prev = cur
        marked = {e for e, ok in stats.items() if ok[0] or ok[1]}
        if not marked:
            break
        for e in marked:
            if e not in rounds:
                rounds[e] = rnd
        new_current = {}
        for p, cnt in current.items():
            fm = canonical(p[0], p[1]) in marked
            lm = canonical(p[-2], p[-1]) in marked
            start = 1 if fm else 0
            stop = len(p) - (1 if lm else 0)
            np = p[start:stop]
            if len(np) >= 2:
                new_current[np] = new_current.get(np, 0) + cnt
        current = new_current
        rnd += 1

    core_edges = set()
    for p in current:
        prev = p[0]
        for cur in p[1:]:
            core_edges.add(canonical(prev, cur))
            prev = cur
    return rounds, current, core_edges


def validate_order_and_width(order, core_links, scopes):
    m = len(core_links)
    if len(order) != m:
        raise Invalid()
    index = {e: i for i, e in enumerate(core_links)}
    seen = set()
    pos_of_var = [0] * m
    for pos, e in enumerate(order):
        if e not in index:
            raise Invalid()
        if e in seen:
            raise Invalid()
        seen.add(e)
        pos_of_var[index[e]] = pos
    if len(seen) != m:
        raise Invalid()

    # Primal graph: every phi scope is a clique.
    adj = [set() for _ in range(m)]
    for scope in scopes:
        xs = list(scope)
        for i in range(len(xs)):
            a = xs[i]
            for j in range(i + 1, len(xs)):
                b = xs[j]
                adj[a].add(b)
                adj[b].add(a)

    for pos, e in enumerate(order):
        x = index[e]
        neigh = list(adj[x])
        if len(neigh) > 4:
            raise Invalid()
        for i in range(len(neigh)):
            a = neigh[i]
            for j in range(i + 1, len(neigh)):
                b = neigh[j]
                adj[a].add(b)
                adj[b].add(a)
        for y in neigh:
            adj[y].discard(x)
        adj[x].clear()
    return pos_of_var


def build_scopes_and_occurrences(core_paths, edge_index):
    m = len(edge_index)
    scopes = [{i} for i in range(m)]
    occurrences = []

    def ctx_spec(w, dest):
        f = canonical(w, dest)
        fi = edge_index.get(f)
        if fi is None:
            raise Invalid()
        return (fi, w > dest)

    for p, cnt in core_paths.items():
        plen = len(p)
        for i in range(plen - 1):
            a = p[i]
            b = p[i + 1]
            center = edge_index[canonical(a, b)]
            if a < b:
                # The occurrence already runs in canonical direction.
                if i == 0:
                    left = 0
                else:
                    left = ctx_spec(p[i - 1], a)
                if i + 2 >= plen:
                    right = 2
                else:
                    right = ctx_spec(b, p[i + 2])
            else:
                # Reverse the whole path; the occurrence is then b -> a.
                if i + 2 >= plen:
                    left = 0
                else:
                    left = ctx_spec(p[i + 2], b)
                if i == 0:
                    right = 2
                else:
                    right = ctx_spec(a, p[i - 1])
            occurrences.append((center, left, right, cnt))
            s = scopes[center]
            if type(left) is tuple:
                s.add(left[0])
            if type(right) is tuple:
                s.add(right[0])
    return scopes, occurrences


def make_factors(m, scopes, occurrences):
    groups = [dict() for _ in range(m)]
    for center, left, right, cnt in occurrences:
        d = groups[center]
        key = (left, right)
        d[key] = d.get(key, 0) + cnt

    factors = []
    for center in range(m):
        others = sorted(scopes[center] - {center})
        # Put the center in the first (most significant) slot.
        vars = (center,) + tuple(others)
        k = len(vars)
        tail = 3 ** (k - 1)
        vals = [0] * (3 ** k)
        posmap = {v: j for j, v in enumerate(vars)}
        combos = list(product(range(3), repeat=k - 1))
        for (left, right), cnt in groups[center].items():
            for ci, cstates in enumerate(combos):
                if type(left) is int:
                    ls = left
                else:
                    st = cstates[posmap[left[0]] - 1]
                    ls = 2 - st if left[1] else st
                if type(right) is int:
                    rs = right
                else:
                    st = cstates[posmap[right[0]] - 1]
                    rs = 2 - st if right[1] else st
                target = G[ls][rs]
                vals[target * tail + ci] += cnt
        factors.append((vars, vals))
    return factors


def run_ve(factors, m, pos_of_var, evidence=None):
    """Exact sum of product. evidence is (var_index, state) or None."""
    buckets = [[] for _ in range(m)]
    constant = 1

    def add_factor(fvars, vals):
        p = min(pos_of_var[v] for v in fvars)
        buckets[p].append((fvars, vals))

    for fvars, vals in factors:
        add_factor(fvars, vals)
    if evidence is not None:
        evar, estate = evidence
        ev = [0, 0, 0]
        ev[estate] = 1
        add_factor((evar,), ev)

    for p in range(m):
        selected = buckets[p]
        if not selected:
            # An unconstrained ternary variable contributes a factor of 3.
            constant *= 3
            continue
        union_set = set()
        for fvars, vals in selected:
            union_set.update(fvars)
        union = sorted(union_set, key=lambda x: pos_of_var[x])
        k = len(union)
        rem_size = 3 ** (k - 1)
        upos = {v: j for j, v in enumerate(union)}
        prepared = []
        for fvars, vals in selected:
            prepared.append((tuple(upos[v] for v in fvars), vals))

        msg = [0] * rem_size
        total_assignments = 3 ** k
        for flat in range(total_assignments):
            q = flat
            states = [0] * k
            for j in range(k - 1, -1, -1):
                states[j] = q % 3
                q //= 3
            prod = 1
            for positions, vals in prepared:
                fi = 0
                for pos in positions:
                    fi = fi * 3 + states[pos]
                prod *= vals[fi]
                if prod == 0:
                    break
            msg[flat % rem_size] += prod

        buckets[p] = []
        if k == 1:
            constant *= msg[0]
        else:
            rem = union[1:]
            nxt = min(pos_of_var[v] for v in rem)
            buckets[nxt].append((tuple(rem), msg))
    return constant


def score_queries(queries, ixps, priors, declared, core_marginals):
    uniform = (Fraction(1, 3), Fraction(1, 3), Fraction(1, 3))
    out = []

    def lookup(a, b):
        e = canonical(a, b)
        if e in declared:
            vec = declared[e]
        elif e in core_marginals:
            vec = core_marginals[e]
        elif e in priors:
            vec = priors[e]
        else:
            vec = uniform
        if a > b:
            return (vec[2], vec[1], vec[0])
        return vec

    for qid, rawpath, (ta, tb) in queries:
        p = normalize_path(rawpath, ixps)
        if len(set(p)) != len(p):
            out.append({
                "id": qid,
                "path": list(p),
                "status": "loop",
                "score": None,
                "full": None,
                "witness": None,
                "leaked": None,
            })
            continue

        if len(p) <= 2:
            score = 1.0
            full = 1.0
            witness = None
            leaked = False
        else:
            probs = [lookup(p[i], p[i + 1]) for i in range(len(p) - 1)]

            # Put all link probabilities in this query over one common

            # Put all link probabilities in this query over one common
            # denominator.  This keeps score/witness/leak comparisons exact
            # without creating enormous reduced fractions for long paths.
            den = 1
            for vec in probs:
                for x in vec:
                    d = x.denominator
                    den = den // gcd(den, d) * d
            iprobs = []
            for vec in probs:
                iprobs.append(tuple(
                    x.numerator * (den // x.denominator) for x in vec
                ))

            den2 = den * den
            best_num = None
            witness = None
            for i in range(len(iprobs) - 1):
                u = iprobs[i][0]
                d = iprobs[i + 1][2]
                score_num = den * (u + d) - u * d
                if best_num is None or score_num < best_num:
                    best_num = score_num
                    witness = i
            score = best_num / den2
            leaked = best_num * tb < ta * den2

            # full is only reported as a tolerant JSON number; a stable
            # floating-point DP is sufficient and avoids Q**path_length ints.
            up = 1.0
            peer = 0.0
            down = 0.0
            for u, h, d in iprobs:
                fu = u / den
                fh = h / den
                fd = d / den
                up, peer, down = up * fu, up * fh, (up + peer + down) * fd
            full = up + peer + down

        out.append({
            "id": qid,
            "path": list(p),
            "status": "ok",
            "score": float(score),
            "full": float(full),
            "witness": witness,
            "leaked": bool(leaked),
        })
    return out


def solve(data):
    ixps, rib, priors, declared, order, queries = validate(data)

    # Normalize and aggregate accepted RIB paths.
    aggregated = {}
    all_edges = set()
    for rawpath, count in rib:
        p = normalize_path(rawpath, ixps)
        if len(p) < 2 or len(set(p)) != len(p):
            continue
        aggregated[p] = aggregated.get(p, 0) + count
        prev = p[0]
        for cur in p[1:]:
            all_edges.add(canonical(prev, cur))
            prev = cur
    if len(all_edges) > 4096:
        raise Invalid()

    rounds, core_paths, core_edges = peel(aggregated)
    if len(core_edges) > 64:
        raise Invalid()
    core_links = sorted(core_edges)
    edge_index = {e: i for i, e in enumerate(core_links)}

    scopes, occurrences = build_scopes_and_occurrences(core_paths, edge_index)
    pos_of_var = validate_order_and_width(order, core_links, scopes)

    factors = make_factors(len(core_links), scopes, occurrences)
    m = len(core_links)
    if m == 0:
        Z = 1
    else:
        Z = run_ve(factors, m, pos_of_var)
    if Z == 0:
        return {"error": "zero-partition"}

    core_marginals = {}
    for i, e in enumerate(core_links):
        nums = []
        for t in range(3):
            nums.append(run_ve(factors, m, pos_of_var, (i, t)))
        core_marginals[e] = tuple(Fraction(n, Z) for n in nums)

    uniform = (Fraction(1, 3), Fraction(1, 3), Fraction(1, 3))
    links_out = []
    for e in sorted(all_edges):
        if e in edge_index:
            rnd = 0
            prob = core_marginals[e]
        else:
            rnd = rounds.get(e)
            if rnd is None:
                # Should be unreachable for a valid peeling computation.
                raise Invalid()
            prob = priors.get(e, uniform)
        links_out.append({
            "link": [e[0], e[1]],
            "round": rnd,
            "prob": [float(prob[0]), float(prob[1]), float(prob[2])],
        })

    queries_out = score_queries(queries, ixps, priors, declared, core_marginals)
    return {"version": 1, "links": links_out, "queries": queries_out}


def main():
    try:
        data = parse_request()
        answer = solve(data)
    except Invalid:
        answer = {"error": "invalid"}
    except Exception:
        # A malformed or out-of-domain request must not produce a traceback.
        answer = {"error": "invalid"}
    sys.stdout.write(json.dumps(answer, separators=(",", ":"), allow_nan=False))
    sys.stdout.write("\n")


if __name__ == "__main__":
    main()

